#!/usr/bin/env node
// Generates app/src/main/java/dev/rei/android/ui/icons/ReiIcons.kt from the lucide icon data in the workspace's
// node_modules, for the names mapped in apps/web/src/components/Icon.tsx plus a few extra names the Android shell needs.
// Run from anywhere: `node apps/android/tools/generate-icons.mjs`. The generated file is checked in.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { shapePath } from "./svg.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "../../..");
const iconTsx = join(root, "apps/web/src/components/Icon.tsx");
const lucideDir = join(root, "node_modules/lucide-react");
const iconsDir = join(lucideDir, "dist/esm/icons");
const out = join(here, "../app/src/main/java/dev/rei/android/ui/icons/ReiIcons.kt");
const STROKE = 1.75;

// Names the shell and the primitives need that Icon.tsx does not map: name -> lucide icon file.
const EXTRAS = {
  book: "book",
  moreVertical: "ellipsis-vertical",
  eyeOff: "eye-off",
  star: "star",
};
// Icons drawn solid, with their own geometry (the web draws Stop as a smaller filled square).
const FILLED = {
  stop: ["M8.5 6h7A2.5 2.5 0 0 1 18 8.5v7a2.5 2.5 0 0 1-2.5 2.5h-7A2.5 2.5 0 0 1 6 15.5v-7A2.5 2.5 0 0 1 8.5 6z"],
};

const kebab = (component) =>
  component
    .replace(/([a-z])([A-Z])/g, "$1-$2")
    .replace(/([A-Za-z])(\d)/g, "$1-$2")
    .toLowerCase();

// "Image as ImageIcon" imports the lucide component `Image`; the mapping value uses the local name.
function parseMap(source) {
  const imports = new Map();
  for (const [, body] of source.matchAll(/import \{([^}]*)\} from "lucide-react";/g)) {
    for (const part of body
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean)) {
      const [imported, local = imported] = part.split(/\s+as\s+/);
      imports.set(local, imported);
    }
  }
  const block = source.match(/const ICONS = \{([\s\S]*?)\} satisfies/);
  if (!block) throw new Error("Could not find the ICONS map in Icon.tsx");
  const map = [];
  for (const [, name, local] of block[1].matchAll(/^\s*(\w+):\s*(\w+),/gm)) {
    const imported = imports.get(local);
    if (!imported) throw new Error(`Icon.tsx maps ${name} to ${local}, which is not imported from lucide-react`);
    map.push([name, kebab(imported)]);
  }
  return map;
}

// Some lucide files are aliases: \`export { default } from './rotate-ccw-clock.mjs'\`. Follow them to the real icon.
async function load(file) {
  let current = file;
  for (let hops = 0; hops < 4; hops++) {
    const path = join(iconsDir, `${current}.mjs`);
    if (!existsSync(path)) throw new Error(`lucide-react has no icon "${current}" (${path})`);
    const alias = readFileSync(path, "utf8").match(/export \{ default \} from '\.\/([\w-]+)\.mjs'/);
    if (alias) {
      current = alias[1];
      continue;
    }
    const { __iconData } = await import(pathToFileURL(path).href);
    if (!__iconData) throw new Error(`${current}.mjs does not export __iconData`);
    return __iconData.node.map(([tag, attrs]) => shapePath(tag, attrs));
  }
  throw new Error(`Too many alias hops for ${file}`);
}

const pascal = (name) => name[0].toUpperCase() + name.slice(1);
const version = JSON.parse(readFileSync(join(lucideDir, "package.json"), "utf8")).version;
const entries = [...parseMap(readFileSync(iconTsx, "utf8")), ...Object.entries(EXTRAS)];
const seen = new Set();
const lines = [];
for (const [name, file] of entries.sort(([a], [b]) => a.localeCompare(b))) {
  if (seen.has(name)) throw new Error(`Duplicate icon name ${name}`);
  seen.add(name);
  const filled = FILLED[name];
  const paths = filled ?? (await load(file));
  const quoted = paths.map((d) => JSON.stringify(d).replaceAll("$", "\\$")).join(",\n            ");
  lines.push(
    `    /** lucide \`${filled ? "square" : file}\`${filled ? ", solid" : ""}. */\n` +
      `    val ${pascal(name)}: ImageVector by lazy {\n        icon(\n            "${pascal(name)}",\n            ${quoted},${filled ? "\n            filled = true," : ""}\n        )\n    }`,
  );
}

const kotlin = `// GENERATED by apps/android/tools/generate-icons.mjs from lucide-react ${version}. Do not edit by hand.
// Names match the \`ICONS\` map in apps/web/src/components/Icon.tsx, plus a few extras the Android shell needs.
// Regenerate with: node apps/android/tools/generate-icons.mjs
package dev.rei.android.ui.icons

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/** Lucide line icons on a 24dp grid, stroked ${STROKE}, tinted by the surrounding \`LocalContentColor\`. */
object ReiIcons {
${lines.join("\n")}
}

private fun icon(name: String, vararg paths: String, filled: Boolean = false): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
        .apply {
            paths.forEach { d ->
                addPath(
                    pathData = PathParser().parsePathString(d).toNodes(),
                    fill = if (filled) SolidColor(Color.Black) else null,
                    stroke = SolidColor(Color.Black),
                    strokeLineWidth = ${STROKE}f,
                    strokeLineCap = StrokeCap.Round,
                    strokeLineJoin = StrokeJoin.Round,
                )
            }
        }
        .build()
`;
writeFileSync(out, kotlin);
console.log(`Wrote ${seen.size} icons to ${out}`);
